<template>
  <section class="teacher-learning">
    <div class="learning-toolbar"><div class="learning-filters"><label>教学班<select v-model="className" :disabled="loading" aria-label="学习统计教学班" @change="changeClass"><option v-for="name in dashboard?.classes || []" :key="name" :value="name">{{ name }}</option></select></label><input v-model.trim="search" type="search" placeholder="搜索姓名或学号" aria-label="搜索学习统计学生" /></div><div class="toolbar-actions"><button type="button" @click="rulesOpen = true">统计规则</button><button type="button" :disabled="loading" @click="load">刷新</button></div></div>
    <p v-if="error" class="learning-error" role="alert">{{ error }}</p>
    <div v-if="loading && !dashboard" class="learning-empty">加载中…</div>
    <template v-if="dashboard"><div class="learning-stats"><div v-for="stat in statCards" :key="stat.key" class="metric-card" :class="stat.tone"><div class="metric-heading"><span>{{ stat.label }}</span><span class="metric-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path stroke-linecap="round" stroke-linejoin="round" :d="stat.icon" /></svg></span></div><strong>{{ stat.value ?? '—' }}</strong></div></div>
      <div class="learning-layout"><section class="learning-panel radar-panel"><header><div class="panel-title"><span class="panel-mark"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="m12 3 9 7-3 10H6L3 10 12 3Z"/><path d="m12 8 4.5 3.5-1.5 5h-6l-1.5-5L12 8Z"/></svg></span><h2>班级能力雷达</h2></div></header><LearningRadar :dimensions="dashboard.dimensions" show-bars /></section><section class="learning-panel ranking-panel"><header><div class="panel-title"><span class="panel-mark"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M4 20h16M7 16v-5m5 5V4m5 12V8"/></svg></span><h2>班级排行</h2></div><span class="panel-count">{{ filtered.length }} 人</span></header><LearningRanking :pagination-key="className + search + experimentCode" :rows="filtered" management @select="openDetail" /></section></div>
    </template>
    <LearningRulesDialog v-if="rulesOpen" :experiment-scoped="!!experimentCode" @close="rulesOpen = false" />
    <div v-if="detailOpen" class="learning-mask" @click.self="closeDetail" @keydown.esc="closeDetail">
      <section class="learning-dialog student-detail-dialog" role="dialog" aria-modal="true" aria-label="学生学习详情" ref="detailPanel" tabindex="-1">
        <header><div class="student-detail-identity"><span class="student-detail-avatar" aria-hidden="true">{{ (detail?.name || selectedRanking?.name)?.slice(0, 1) || '—' }}</span><div><h2>{{ detail?.name || selectedRanking?.name || '学生详情' }}</h2><p>{{ className }}<span v-if="detail?.username"> · {{ detail.username }}</span></p></div></div><button type="button" @click="closeDetail">关闭</button></header>
        <p v-if="detailError" class="learning-error" role="alert">{{ detailError }}</p>
        <div v-if="detailLoading" class="learning-empty">加载中…</div>
        <template v-else-if="detail">
          <div class="individual-summary"><div><span>个人积分</span><strong>{{ detail.totalPoints }}</strong></div><div><span>{{ experimentCode ? '报告成绩' : '报告均分' }}</span><strong>{{ detail.averageScore ?? '—' }}</strong></div><div><span>班级排名</span><strong>{{ selectedRanking?.rank || '—' }}</strong></div></div>
          <div class="individual-records">
            <article v-for="record in detailItems" :key="record.code" class="individual-record">
              <header><h3>{{ record.name }}</h3><span class="status-label">{{ learningState(record.state) }}</span></header>
              <ol class="record-milestones"><li v-for="step in recordMilestones(record)" :key="step.label" :class="{ completed: step.done }"><span class="milestone-dot"><svg v-if="step.done" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="m3 8 3 3 7-7" /></svg></span><strong>{{ step.label }}</strong><span>{{ step.status }}</span></li></ol>
              <dl class="record-dates"><div><dt>分配时间</dt><dd>{{ learningDate(record.assignedAt) }}</dd></div><div><dt>实验完成时间</dt><dd>{{ learningDate(record.finishedAt) }}</dd></div><div><dt>报告截止时间</dt><dd>{{ learningDate(record.dueAt) }}</dd></div><div><dt>批阅时间</dt><dd>{{ learningDate(record.gradedAt) }}</dd></div></dl>
              <section class="individual-points"><h4>积分明细 <span>{{ record.points }} 分</span></h4><div v-if="record.pointItems.length" class="individual-point-list"><div v-for="item in record.pointItems" :key="item.label"><span>{{ item.label }}</span><strong>+{{ item.points }}</strong></div></div><p v-else class="individual-empty">暂无积分记录</p></section>
              <div v-if="record.graded || record.reflection" class="individual-feedback"><section><h4>教师评语</h4><p>{{ record.comment || '暂无评语' }}</p></section><section><h4>学生订正 <span class="status-label" :class="{ complete: record.reflectionCurrent }">{{ record.reflectionCurrent ? '已订正' : record.reflection ? '待更新' : '待订正' }}</span></h4><p>{{ record.reflection || '暂无订正' }}</p><div v-if="record.reflectionAt" class="record-time">{{ learningDate(record.reflectionAt) }}</div></section></div>
            </article>
            <div v-if="!detail.records.length" class="learning-empty">暂无已分配实验</div>
          </div>
          <ListPagination v-model:page="detailPage" v-model:page-size="detailSize" :total="detailTotal" />
          <details class="individual-abilities"><summary>个人能力记录</summary><dl><div v-for="dimension in detail.dimensions" :key="dimension.key"><dt>{{ dimension.label }}</dt><dd>{{ dimension.value ?? '—' }}</dd></div></dl></details>
        </template>
      </section>
    </div>
  </section>
</template>
<script setup>
import ListPagination from '../common/ListPagination.vue'
import { usePagination } from '../../composables/usePagination'
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { learningApi, learningError } from '../../api/learning'
import { learningDate, learningState } from '../../utils/learning'
import LearningRadar from '../learning/LearningRadar.vue'
import LearningRanking from '../learning/LearningRanking.vue'
import LearningRulesDialog from '../learning/LearningRulesDialog.vue'
const props = defineProps({ experimentCode: { type: String, default: '' } })
const dashboard = ref(null), className = ref(''), search = ref(''), loading = ref(false), error = ref(''), rulesOpen = ref(false)
const detailOpen = ref(false), detail = ref(null), detailLoading = ref(false), detailError = ref(''), detailPanel = ref(null)
const selectedRanking = ref(null)
const filtered = computed(() => (dashboard.value?.leaderboard || []).filter(row => !search.value || (row.name + ' ' + row.username).toLowerCase().includes(search.value.toLowerCase())))
const statCards = computed(() => dashboard.value ? [
  { key: 'students', label: props.experimentCode ? '已分配人数' : '班级人数', value: dashboard.value.studentCount, tone: 'metric-indigo', icon: 'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M14 3.13a4 4 0 0 1 0 7.75M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z' },
  { key: 'active', label: '已获积分人数', value: dashboard.value.activeCount, tone: 'metric-teal', icon: 'm8 12 3 3 5-6M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z' },
  { key: 'average', label: '平均积分', value: dashboard.value.averagePoints, tone: 'metric-blue', icon: 'M4 20h16M7 15V9m5 6V4m5 11v-3' },
  { key: 'highest', label: '最高积分', value: dashboard.value.leaderboard[0]?.points, tone: 'metric-violet', icon: 'm4 16 5-5 4 4 7-10m-6 0h6v6M4 21h16' }
] : [])
let sequence = 0, detailSequence = 0
async function load() {
  const run = ++sequence; loading.value = true; error.value = ''
  try { const { data } = await learningApi.teacher(className.value || undefined, props.experimentCode || undefined); if (run !== sequence) return; dashboard.value = data; className.value = data.className }
  catch (e) { if (run === sequence) error.value = learningError(e) }
  finally { if (run === sequence) loading.value = false }
}
function changeClass() { closeDetail(); search.value = ''; dashboard.value = null; load() }
async function openDetail(row) {
  const run = ++detailSequence; const requestedClass = className.value, requestedExperiment = props.experimentCode
  selectedRanking.value = row; detail.value = null; detailError.value = ''; detailLoading.value = true; detailOpen.value = true
  await nextTick(); detailPanel.value?.focus()
  if (run !== detailSequence) return
  try { const { data } = await learningApi.detail(row.userId, requestedClass, requestedExperiment || undefined); if (run === detailSequence) detail.value = data }
  catch (e) { if (run === detailSequence) detailError.value = learningError(e) }
  finally { if (run === detailSequence) detailLoading.value = false }
}
function closeDetail() { detailSequence++; detailOpen.value = false; detail.value = null; selectedRanking.value = null }
function recordMilestones(record) {
  return [
    { label: '实验准备', done: record.prepared, status: record.prepared ? '已完成' : '未完成' },
    { label: '实物实验', done: record.finished, status: record.finished ? '已完成' : '未完成' },
    { label: '数据记录', done: record.dataRecorded, status: record.dataRecorded ? '已记录' : '未记录' },
    { label: '实验报告', done: record.submitted, status: record.graded ? '已批阅' : record.submitted ? '待批阅' : '未提交' },
    { label: '反馈订正', done: record.reflectionCurrent, status: record.reflectionCurrent ? '已订正' : record.graded ? record.reflection ? '待更新' : '待订正' : '未开始' }
  ]
}
watch(() => props.experimentCode, () => { closeDetail(); dashboard.value = null; load() })
onMounted(load)
onBeforeUnmount(() => { sequence++; detailSequence++ })
const { page: detailPage, pageSize: detailSize, total: detailTotal, items: detailItems } = usePagination(() => detail.value?.records || [], [() => selectedRanking.value?.userId, () => props.experimentCode])
</script>
